    option_id = 15133

    for category, prompt_groups in category_specs:
        category_start_len = len(generated_questions)
        for prompts, option_specs in prompt_groups:
            for prompt in prompts:
                generated_questions.append(make_question(question_id, category, prompt, option_id, option_specs))
                question_id += 1
                option_id += len(option_specs)

        category_count = len(generated_questions) - category_start_len
        if category_count != 30:
            raise ValueError(f"Expected 30 generated questions for {category}, got {category_count}")

    return generated_questions


