_arts_generated_oids = {option["option_id"] for question in _ARTS_EXPANSION for option in question.get("options", [])}
if _arts_existing_oids & _arts_generated_oids:
    raise ValueError("Arts expansion option IDs overlap with existing options")

QUESTIONS_POOL_ENHANCED.extend(_ARTS_EXPANSION)


